## Why This Question Is Asked
This question probes end-to-end orchestration of real-time collaboration, including WebSocket presence, autosave determinism, offline recovery, and conflict resolution. It also assesses test isolation strategies and how to model eventual consistency in tests.

## Key Concepts
- Real-time collaboration, presence, and WebSocket event handling
- Autosave semantics and determinism via clock mocks
- Offline/online recovery and conflict resolution strategies
- Test data isolation and environment management
- Observability: asserting store state and client views align

## Code Example
```javascript
// Playwright test setup with two isolated contexts
const { test, expect } = require('@playwright/test');

test.describe('Collaborative Document Editor', () => {
  let docId;

  test.beforeEach(async ({ request }) => {
    docId = `test-doc-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  });

  test('real-time presence and autosave sync between two users', async ({ browser }) => {
    const userA = await browser.newContext();
    const userB = await browser.newContext();

    const pageA = await userA.newPage();
    const pageB = await userB.newPage();

    await pageA.goto(`/doc/${docId}`);
    await pageB.goto(`/doc/${docId}`);

    // Verify presence indicators show both users
    await expect(pageA.locator('.presence')).toContainText('User B');
    await expect(pageB.locator('.presence')).toContainText('User A');

    // User A types; User B should see it within 1-2 seconds
    await pageA.locator('.editor').fill('Hello from User A');
    await expect(pageB.locator('.editor')).toHaveValue('Hello from User A', { timeout: 3000 });

    // Verify autosave to data store (mocked interval: 2s)
    await pageA.waitForTimeout(2500);
    const storedDoc = await request.get(`/api/docs/${docId}`);
    expect((await storedDoc.json()).content).toBe('Hello from User A');
  });

  test('offline reconnection and conflict resolution', async ({ browser }) => {
    const userA = await browser.newContext();
    const userB = await browser.newContext();

    const pageA = await userA.newPage();
    const pageB = await userB.newPage();

    await pageA.goto(`/doc/${docId}`);
    await pageB.goto(`/doc/${docId}`);

    // Simulate offline for User B
    await pageB.context().setOffline(true);
    await pageA.locator('.editor').fill('User A edit');
    await pageB.waitForTimeout(1000);

    // Reconnect User B
    await pageB.context().setOffline(false);
    await expect(pageB.locator('.editor')).toHaveValue('User A edit', { timeout: 5000 });

    // Concurrent edits - last-write-wins conflict resolution
    await pageB.locator('.editor').fill('User B edit');
    await pageA.locator('.editor').fill('User A edit');
    await pageB.waitForTimeout(2500); // Wait for autosave

    const finalDoc = await request.get(`/api/docs/${docId}`);
    expect((await finalDoc.json()).content).toMatch(/User (A|B) edit/);
  });
});
```

## Why This Is Asked
Testing offline-first sync across devices is a realistic challenge for consumer apps with data integrity concerns, multi-device usage, and eventual consistency.

## Key Concepts
- Offline-first architecture: Data is persisted locally and synced when connectivity is restored
- Conflict resolution strategy: Merge (combine changes) vs. Last-Write-Wins (most recent timestamp wins)
- Test isolation across devices: Each Playwright context maintains separate local storage and cookies
- Deterministic network shaping: Use Playwright's `route` or Cypress's `server` to intercept and delay requests

## Code Example
```javascript
const { test, expect } = require('@playwright/test');

test('offline-first sync with conflict resolution', async ({ browser }) => {
  // Create two isolated device contexts
  const ctxA = await browser.newContext();
  const ctxB = await browser.newContext();

  const pageA = await ctxA.newPage();
  const pageB = await ctxB.newPage();

  // Simulate offline on both devices
  await pageA.route('**/api/**', route => route.abort('failed'));
  await pageB.route('**/api/**', route => route.abort('failed'));

  // Device A creates a note offline
  await pageA.goto('/app');
  await pageA.fill('[data-testid="note-input"]', 'Note from A');
  await pageA.click('[data-testid="save"]');

  // Device B creates a note offline
  await pageB.goto('/app');
  await pageB.fill('[data-testid="note-input"]', 'Note from B');
  await pageB.click('[data-testid="save"]');

  // Restore connectivity
  await pageA.unrouteAll();
  await pageB.unrouteAll();

  // Wait for sync and verify
  await pageA.reload();
  await pageB.reload();

  await expect(pageA.locator('[data-testid="notes"]')).toContainText('Note from A');
  await expect(pageA.locator('[data-testid="notes"]')).toContainText('Note from B');
});
```

